                `);for(const d of decisions){const action=(d.action||'NO_ACTION').toUpperCase();updateStmt.run([action,d.remarks||null,now,d.id,client_gstin,return_period]);}updateStmt.finalize();db2.run('COMMIT',async commitErr=>{if(commitErr)return res.status(500).json({success:false,error:'Failed to persist decisions'});try{const metrics=await recalculateBatchMetrics(client_gstin,return_period);res.json({success:true,message:'Review successfully submitted to your CA! Thank you.',metrics});}catch(mErr){res.json({success:true,message:'Decisions recorded successfully'});}});});});});app2.post('/api/ims/update-actions',(req,res)=>{const {gstin,period,updates}=req.body;if(!gstin||!period||!Array.isArray(updates)){return res.status(400).json({success:false,error:'gstin, period and updates array are required'});}const now=Date.now();db2.serialize(()=>{db2.run('BEGIN TRANSACTION');const stmt=db2.prepare(`
